(()=>{const key=document.body.dataset.category,lang=new URLSearchParams(location.search).get('lang')||'en',valid=['en','nl','de','fr','es','it','pt','pl','sv'],current=valid.includes(lang)?lang:'en';const names={en:{shoes:'Shoes',hoodies:'Hoodies',tshirts:'T-Shirts',jackets:'Jackets',pants:'Pants',bags:'Bags',watches:'Watches',electronics:'Electronics',accessories:'Accessories',other:'Other Stuff'},nl:{shoes:'Schoenen',hoodies:'Hoodies',tshirts:'T-shirts',jackets:'Jassen',pants:'Broeken',bags:'Tassen',watches:'Horloges',electronics:'Elektronica',accessories:'Accessoires',other:'Overig'},de:{shoes:'Schuhe',hoodies:'Hoodies',tshirts:'T-Shirts',jackets:'Jacken',pants:'Hosen',bags:'Taschen',watches:'Uhren',electronics:'Elektronik',accessories:'Accessoires',other:'Sonstiges'},fr:{shoes:'Chaussures',hoodies:'Sweats à capuche',tshirts:'T-shirts',jackets:'Vestes',pants:'Pantalons',bags:'Sacs',watches:'Montres',electronics:'Électronique',accessories:'Accessoires',other:'Autres'},es:{shoes:'Zapatos',hoodies:'Sudaderas',tshirts:'Camisetas',jackets:'Chaquetas',pants:'Pantalones',bags:'Bolsos',watches:'Relojes',electronics:'Electrónica',accessories:'Accesorios',other:'Otros'},it:{shoes:'Scarpe',hoodies:'Felpe',tshirts:'T-shirt',jackets:'Giacche',pants:'Pantaloni',bags:'Borse',watches:'Orologi',electronics:'Elettronica',accessories:'Accessori',other:'Altro'},pt:{shoes:'Sapatos',hoodies:'Hoodies',tshirts:'T-shirts',jackets:'Casacos',pants:'Calças',bags:'Bolsas',watches:'Relógios',electronics:'Eletrónica',accessories:'Acessórios',other:'Outros'},pl:{shoes:'Buty',hoodies:'Bluzy',tshirts:'T-shirty',jackets:'Kurtki',pants:'Spodnie',bags:'Torby',watches:'Zegarki',electronics:'Elektronika',accessories:'Akcesoria',other:'Inne'},sv:{shoes:'Skor',hoodies:'Hoodies',tshirts:'T-shirts',jackets:'Jackor',pants:'Byxor',bags:'Väskor',watches:'Klockor',electronics:'Elektronik',accessories:'Accessoarer',other:'Övrigt'}};const strings={en:['Category guide','Browse the current {name} selection in FindSpreadsheet. This guide helps you check a listing before you decide.','Open {name} in database','All categories','How to use this {name} guide','A spreadsheet is a discovery tool, not a final product record. Open the live listing before payment and compare the title, selected option, size, colour, seller notes and price shown at that moment.','Use the visible product information to make a deliberate decision. Listing availability, options, parcel rules and delivery services can change, so this page does not promise stock, delivery dates, prices or customs outcomes.','What to check before opening a product','Confirm the exact option, size, colour and quantity.','Compare the current product title and visible images.','Read live seller notes and destination-specific shipping details.','Questions before you choose','Does this page sell products?','No. It is an independent category guide. The live record and available options are in FindSpreadsheet.','Can the guide confirm quality or delivery?','No. Images can show visible details, but they cannot guarantee fit, material, authenticity, delivery timing or customs results.','Independent category research. Current product records are available in FindSpreadsheet.'],nl:['Categoriegids','Bekijk de actuele selectie {name} in FindSpreadsheet. Deze gids helpt je een listing te controleren voordat je kiest.','Open {name} in database','Alle categorieën','Zo gebruik je deze gids voor {name}','Een spreadsheet is een hulpmiddel om te ontdekken, geen definitief productrecord. Open vóór betaling de actuele listing en vergelijk titel, gekozen optie, maat, kleur, verkopersnotities en prijs.','Gebruik zichtbare productinformatie voor een bewuste keuze. Beschikbaarheid, opties, pakketregels en bezorgdiensten kunnen wijzigen; deze pagina belooft geen voorraad, levertijd, prijs of douane-uitkomst.','Controleer vóór het openen van een product','Bevestig optie, maat, kleur en aantal.','Vergelijk actuele producttitel en zichtbare afbeeldingen.','Lees actuele verkopersnotities en verzendgegevens voor je bestemming.','Vragen vóór je kiest','Verkoopt deze pagina producten?','Nee. Dit is een onafhankelijke categoriegids. Het actuele record en opties staan in FindSpreadsheet.','Kan de gids kwaliteit of levering bevestigen?','Nee. Afbeeldingen tonen zichtbare details, maar garanderen geen pasvorm, materiaal, echtheid, levertijd of douane-uitkomst.','Onafhankelijk categorieonderzoek. Actuele productrecords staan in FindSpreadsheet.'],de:['Kategorieleitfaden','Durchsuche die aktuelle Auswahl {name} in FindSpreadsheet. Dieser Leitfaden hilft beim Prüfen eines Angebots vor der Entscheidung.','{name} in Datenbank öffnen','Alle Kategorien','So nutzt du diesen Leitfaden für {name}','Eine Tabelle dient der Entdeckung, nicht als endgültiger Produktdatensatz. Öffne vor der Zahlung das aktuelle Angebot und vergleiche Titel, Variante, Größe, Farbe, Verkäuferhinweise und Preis.','Nutze sichtbare Informationen für eine bewusste Entscheidung. Verfügbarkeit, Optionen, Paketregeln und Versanddienste können sich ändern; diese Seite verspricht keinen Bestand, Termin, Preis oder Zollausgang.','Vor dem Öffnen eines Produkts prüfen','Exakte Variante, Größe, Farbe und Menge bestätigen.','Aktuellen Produkttitel und sichtbare Bilder vergleichen.','Aktuelle Verkäuferhinweise und Versanddetails zum Zielort lesen.','Fragen vor der Auswahl','Verkauft diese Seite Produkte?','Nein. Dies ist ein unabhängiger Kategorieleitfaden. Der aktuelle Datensatz und die Optionen stehen in FindSpreadsheet.','Kann der Leitfaden Qualität oder Lieferung bestätigen?','Nein. Bilder zeigen sichtbare Details, garantieren jedoch weder Passform, Material, Echtheit, Lieferzeit noch Zollergebnis.','Unabhängige Kategorierecherche. Aktuelle Produktdaten stehen in FindSpreadsheet.'],fr:['Guide de catégorie','Parcourez la sélection actuelle {name} dans FindSpreadsheet. Ce guide aide à vérifier une annonce avant de décider.','Ouvrir {name} dans la base','Toutes les catégories','Utiliser ce guide {name}','Un tableur sert à découvrir, pas de fiche produit définitive. Avant le paiement, ouvrez l’annonce active et comparez le titre, l’option, la taille, la couleur, les notes du vendeur et le prix.','Utilisez les informations visibles pour décider avec prudence. Disponibilité, options, règles de colis et services d’expédition peuvent changer; cette page ne promet ni stock, ni délai, ni prix, ni résultat douanier.','À vérifier avant un produit','Confirmez l’option, la taille, la couleur et la quantité.','Comparez le titre actuel et les images visibles.','Lisez les notes du vendeur et l’expédition applicables à votre destination.','Questions avant de choisir','Cette page vend-elle des produits ?','Non. C’est un guide indépendant. La fiche active et les options se trouvent dans FindSpreadsheet.','Le guide confirme-t-il qualité ou livraison ?','Non. Les images montrent des détails visibles mais ne garantissent ni taille, ni matière, ni authenticité, ni délai, ni douane.','Recherche de catégorie indépendante. Les fiches actives sont dans FindSpreadsheet.'],es:['Guía de categoría','Consulta la selección actual de {name} en FindSpreadsheet. Esta guía ayuda a revisar un anuncio antes de decidir.','Abrir {name} en la base','Todas las categorías','Cómo usar esta guía de {name}','Una hoja de cálculo sirve para descubrir, no es una ficha definitiva. Antes de pagar, abre el anuncio actual y compara título, opción, talla, color, notas del vendedor y precio.','Usa la información visible para decidir con cuidado. La disponibilidad, opciones, reglas del paquete y servicios de envío pueden cambiar; esta página no promete existencias, fechas, precios ni resultados aduaneros.','Qué comprobar antes de abrir un producto','Confirma opción, talla, color y cantidad.','Compara el título actual y las imágenes visibles.','Lee notas actuales del vendedor y datos de envío para tu destino.','Preguntas antes de elegir','¿Esta página vende productos?','No. Es una guía independiente. La ficha actual y las opciones están en FindSpreadsheet.','¿La guía confirma calidad o entrega?','No. Las imágenes muestran detalles visibles, pero no garantizan ajuste, material, autenticidad, plazo ni aduana.','Investigación independiente de categorías. Las fichas actuales están en FindSpreadsheet.'],it:['Guida di categoria','Sfoglia la selezione attuale di {name} in FindSpreadsheet. Questa guida aiuta a controllare un annuncio prima di scegliere.','Apri {name} nel database','Tutte le categorie','Come usare questa guida per {name}','Un foglio di calcolo serve per scoprire prodotti, non è una scheda definitiva. Prima del pagamento apri l’annuncio attuale e confronta titolo, opzione, taglia, colore, note del venditore e prezzo.','Usa le informazioni visibili per decidere con attenzione. Disponibilità, opzioni, regole del pacco e servizi di spedizione possono cambiare; questa pagina non promette scorte, date, prezzi o esiti doganali.','Cosa controllare prima di aprire un prodotto','Conferma opzione, taglia, colore e quantità.','Confronta titolo attuale e immagini visibili.','Leggi le note del venditore e i dettagli di spedizione per la destinazione.','Domande prima di scegliere','Questa pagina vende prodotti?','No. È una guida indipendente. Scheda attiva e opzioni sono in FindSpreadsheet.','La guida conferma qualità o consegna?','No. Le immagini mostrano dettagli visibili ma non garantiscono vestibilità, materiale, autenticità, tempi o dogana.','Ricerca di categoria indipendente. Le schede attive sono in FindSpreadsheet.'],pt:['Guia de categoria','Veja a seleção atual de {name} na FindSpreadsheet. Este guia ajuda a verificar um anúncio antes de decidir.','Abrir {name} na base de dados','Todas as categorias','Como usar este guia de {name}','Uma folha de cálculo serve para descobrir produtos, não é um registo final. Antes de pagar, abra o anúncio atual e compare título, opção, tamanho, cor, notas do vendedor e preço.','Use informação visível para decidir com cuidado. Disponibilidade, opções, regras de encomenda e serviços de envio podem mudar; esta página não promete stock, prazos, preços ou resultados aduaneiros.','O que verificar antes de abrir um produto','Confirme opção, tamanho, cor e quantidade.','Compare o título atual e as imagens visíveis.','Leia notas atuais do vendedor e detalhes de envio para o destino.','Perguntas antes de escolher','Esta página vende produtos?','Não. É um guia independente. O registo ativo e as opções estão na FindSpreadsheet.','O guia confirma qualidade ou entrega?','Não. Imagens mostram detalhes visíveis, mas não garantem ajuste, material, autenticidade, prazo ou alfândega.','Pesquisa independente de categoria. Os registos ativos estão na FindSpreadsheet.'],pl:['Przewodnik po kategorii','Przeglądaj aktualny wybór {name} w FindSpreadsheet. Ten przewodnik pomaga sprawdzić ofertę przed decyzją.','Otwórz {name} w bazie','Wszystkie kategorie','Jak korzystać z przewodnika {name}','Arkusz służy do odkrywania produktów, nie jest ostateczną kartą produktu. Przed płatnością otwórz aktualną ofertę i porównaj tytuł, opcję, rozmiar, kolor, notatki sprzedawcy i cenę.','Korzystaj z widocznych informacji, aby podjąć świadomą decyzję. Dostępność, opcje, zasady paczki i usługi wysyłkowe mogą się zmieniać; strona nie obiecuje zapasu, terminu, ceny ani wyniku celnego.','Co sprawdzić przed otwarciem produktu','Potwierdź opcję, rozmiar, kolor i ilość.','Porównaj aktualny tytuł i widoczne zdjęcia.','Przeczytaj bieżące notatki sprzedawcy i szczegóły wysyłki dla celu.','Pytania przed wyborem','Czy ta strona sprzedaje produkty?','Nie. To niezależny przewodnik. Aktualny wpis i opcje są w FindSpreadsheet.','Czy przewodnik potwierdza jakość lub dostawę?','Nie. Zdjęcia pokazują widoczne szczegóły, lecz nie gwarantują dopasowania, materiału, autentyczności, terminu ani odprawy.','Niezależne badanie kategorii. Aktualne wpisy są w FindSpreadsheet.'],sv:['Kategoriguide','Bläddra i det aktuella urvalet {name} i FindSpreadsheet. Guiden hjälper dig att kontrollera en annons före beslut.','Öppna {name} i databasen','Alla kategorier','Så använder du guiden för {name}','Ett kalkylblad hjälper dig att hitta produkter, men är inte en slutlig produktpost. Öppna den aktuella annonsen före betalning och jämför titel, val, storlek, färg, säljaranteckningar och pris.','Använd synlig information för ett medvetet beslut. Tillgänglighet, val, paketregler och frakttjänster kan ändras; sidan lovar inte lager, datum, pris eller tullutfall.','Kontrollera före du öppnar en produkt','Bekräfta exakt val, storlek, färg och antal.','Jämför aktuell produkttitel och synliga bilder.','Läs aktuella säljaranteckningar och fraktdetaljer för destinationen.','Frågor före val','Säljer sidan produkter?','Nej. Det är en oberoende kategoriguide. Aktuell post och alternativ finns i FindSpreadsheet.','Kan guiden bekräfta kvalitet eller leverans?','Nej. Bilder visar synliga detaljer men garanterar inte passform, material, äkthet, tid eller tullutfall.','Oberoende kategoriresearch. Aktuella produktposter finns i FindSpreadsheet.']};const s=strings[current],name=names[current][key],escape=v=>v.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'),fill=v=>escape(v.replaceAll('{name}',name));const routes={shoes:'https://findspreadsheet.com/shoes/',hoodies:'https://findspreadsheet.com/hoodies-sweaters/',tshirts:'https://findspreadsheet.com/t-shirts/',jackets:'https://findspreadsheet.com/jackets/',pants:'https://findspreadsheet.com/pants-shorts/',bags:'https://findspreadsheet.com/search.html?keywords=Bags&channelid=2',watches:'https://findspreadsheet.com/search.html?keywords=Watches&channelid=2',electronics:'https://findspreadsheet.com/electronics/',accessories:'https://findspreadsheet.com/accessories/',other:'https://findspreadsheet.com/other-stuff/'};const slugs={shoes:'shoes',hoodies:'hoodies',tshirts:'t-shirts',jackets:'jackets',pants:'pants',bags:'bags',watches:'watches',electronics:'electronics',accessories:'accessories',other:'other-stuff'};const suffix=current==='en'?'':'?lang='+current;document.documentElement.lang=current;document.title=`${name} LoloBuy Spreadsheet | Category guide`;document.querySelectorAll('[data-category-name]').forEach(el=>el.textContent=name);document.querySelector('[data-copy]').innerHTML=`<p>${fill(s[5])}</p><p>${fill(s[6])}</p>`;document.querySelector('[data-title]').textContent=fill(s[4]);document.querySelector('[data-check-title]').textContent=s[7];document.querySelector('[data-checks]').innerHTML=[s[8],s[9],s[10]].map(x=>`<li>${escape(x)}</li>`).join('');document.querySelector('[data-faq]').innerHTML=`<details open><summary>${escape(s[12])}</summary><p>${escape(s[13])}</p></details><details><summary>${escape(s[14])}</summary><p>${escape(s[15])}</p></details>`;document.querySelector('[data-open]').href=routes[key];document.querySelector('[data-open]').textContent=fill(s[2]);document.querySelector('[data-footer]').textContent=s[16];const menu=document.querySelector('[data-lang-menu]'),button=document.querySelector('[data-lang-button]');button.textContent=current.toUpperCase()+' ▾';menu.innerHTML=valid.map(l=>`<button type="button" data-lang="${l}">${l.toUpperCase()} · ${escape(names[l][key])}</button>`).join('');button.addEventListener('click',()=>menu.classList.toggle('open'));menu.addEventListener('click',e=>{const l=e.target.dataset.lang;if(l)location.href=location.pathname+(l==='en'?'':'?lang='+l)});document.querySelectorAll('[data-nav-page]').forEach(a=>a.href=a.dataset.navPage+suffix);document.querySelector('[data-all-categories]').textContent=s[3];document.querySelector('[data-all-categories]').href='/categories/'+suffix;document.querySelector('[data-breadcrumb-home]').href='/'+suffix;document.querySelector('[data-breadcrumb-categories]').href='/categories/'+suffix;document.querySelector('[data-breadcrumb-home]').textContent='LoloBuy Spreadsheet';document.querySelector('[data-related]').innerHTML=Object.entries(slugs).map(([k,slug])=>`<a href="/${slug}/${suffix}"${k===key?' aria-current="page"':''}>${escape(names[current][k])}</a>`).join('');;const extra={en:{home:'Home',categories:'Categories',details:'Product details',articles:'SEO articles',faq:'FAQ',research:'Independent category research',explore:'Explore other categories'},nl:{home:'Home',categories:'Categorieën',details:'Productdetails',articles:'SEO-artikelen',faq:'Veelgestelde vragen',research:'Onafhankelijk categorieonderzoek',explore:'Andere categorieën bekijken'},de:{home:'Startseite',categories:'Kategorien',details:'Produktdetails',articles:'SEO-Artikel',faq:'Häufige Fragen',research:'Unabhängige Kategorierecherche',explore:'Weitere Kategorien'},fr:{home:'Accueil',categories:'Catégories',details:'Détails produit',articles:'Articles SEO',faq:'Questions fréquentes',research:'Recherche de catégorie indépendante',explore:'Explorer d’autres catégories'},es:{home:'Inicio',categories:'Categorías',details:'Detalles del producto',articles:'Artículos SEO',faq:'Preguntas frecuentes',research:'Investigación independiente de categorías',explore:'Explorar otras categorías'},it:{home:'Home',categories:'Categorie',details:'Dettagli prodotto',articles:'Articoli SEO',faq:'Domande frequenti',research:'Ricerca di categoria indipendente',explore:'Esplora altre categorie'},pt:{home:'Início',categories:'Categorias',details:'Detalhes do produto',articles:'Artigos SEO',faq:'Perguntas frequentes',research:'Pesquisa independente de categoria',explore:'Explorar outras categorias'},pl:{home:'Strona główna',categories:'Kategorie',details:'Szczegóły produktu',articles:'Artykuły SEO',faq:'Najczęstsze pytania',research:'Niezależne badanie kategorii',explore:'Poznaj inne kategorie'},sv:{home:'Hem',categories:'Kategorier',details:'Produktdetaljer',articles:'SEO-artiklar',faq:'Vanliga frågor',research:'Oberoende kategoriresearch',explore:'Utforska andra kategorier'}}[current];document.querySelector('[data-copy-intro]').textContent=fill(s[1]);document.querySelector('[data-breadcrumb-home]').textContent=extra.home;document.querySelector('[data-breadcrumb-categories]').textContent=extra.categories;document.querySelectorAll('nav [data-nav-page]').forEach((node,index)=>node.textContent=[extra.home,extra.categories,extra.details,extra.articles,extra.faq][index]);document.querySelector('.content-grid .eyebrow').textContent=extra.research;document.querySelector('.faq .eyebrow').textContent=extra.faq;document.querySelector('.related h2').textContent=extra.explore})();
